using System;using System.IO;using System.Linq;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine;
public static class RuinsOpeningReview{
 [Serializable]class UvProbe{public float[] uv;}
 static void Check(bool b,string s){if(!b)throw new Exception(s);}
 static Color32[] Shot(Camera c,Vector3 from,Vector3 at,string f){c.transform.position=from;c.transform.LookAt(at);var rt=new RenderTexture(1200,900,24);c.targetTexture=rt;for(int i=0;i<3;i++)c.Render();var prev=RenderTexture.active;RenderTexture.active=rt;var t=new Texture2D(1200,900,TextureFormat.RGB24,false);t.ReadPixels(new Rect(0,0,1200,900),0,0);t.Apply();File.WriteAllBytes(f,t.EncodeToPNG());var a=t.GetPixels32();RenderTexture.active=prev;c.targetTexture=null;UnityEngine.Object.DestroyImmediate(rt);UnityEngine.Object.DestroyImmediate(t);return a;}
 public static void Run(){const string ev="Evidence/Target46Openings";Directory.CreateDirectory(ev);try{
 EditorSceneManager.OpenScene("Assets/RuinsTarget46Output/Room.unity");var root=GameObject.Find("ruins_1").transform.parent.gameObject;var c=UnityEngine.Object.FindAnyObjectByType<Camera>();var sun=UnityEngine.Object.FindObjectsByType<Light>(FindObjectsSortMode.None).Single(x=>x.type==LightType.Directional);sun.transform.rotation=Quaternion.Euler(38,-28,0);RenderSettings.ambientLight=Color.gray*.65f;c.orthographic=false;c.backgroundColor=new Color(.075f,.085f,.1f);var from=new Vector3(15,20,19);var at=new Vector3(0,3.5f,0);
 var pixels=Shot(c,from,at,ev+"/room.png");UnityEngine.Object.DestroyImmediate(root);root=(GameObject)PrefabUtility.InstantiatePrefab(AssetDatabase.LoadAssetAtPath<GameObject>("Assets/RuinsTarget46Output/Structures/Ruins.prefab"));Check(pixels.SequenceEqual(Shot(c,from,at,ev+"/prefab.png")),"Prefab pixels");
 EditorSceneManager.SaveScene(UnityEngine.SceneManagement.SceneManager.GetActiveScene(),"Assets/RuinsTarget46Output/OpeningPersistence.unity");EditorSceneManager.NewScene(NewSceneSetup.EmptyScene);EditorSceneManager.OpenScene("Assets/RuinsTarget46Output/OpeningPersistence.unity");root=GameObject.Find("ruins_1").transform.parent.gameObject;c=UnityEngine.Object.FindAnyObjectByType<Camera>();sun=UnityEngine.Object.FindObjectsByType<Light>(FindObjectsSortMode.None).Single(x=>x.type==LightType.Directional);Check(pixels.SequenceEqual(Shot(c,from,at,ev+"/scene.png")),"Scene pixels");
 var old=(GameObject)PrefabUtility.InstantiatePrefab(AssetDatabase.LoadAssetAtPath<GameObject>("Assets/RuinsTarget41Output/Structures/Ruins.prefab"));int unchanged=0;foreach(Transform t in old.transform){if(!t.name.StartsWith("ruins_"))continue;var a=t.GetComponent<MeshFilter>().sharedMesh;var b=root.transform.Find(t.name).GetComponent<MeshFilter>().sharedMesh;Check(a.vertices.SequenceEqual(b.vertices)&&a.normals.SequenceEqual(b.normals)&&a.uv.SequenceEqual(b.uv)&&a.triangles.SequenceEqual(b.triangles),"Old geometry "+t.name);unchanged++;}Check(unchanged==46,"Old fixture count");
 foreach(int id in new[]{47,48})root.transform.Find("ruins_"+id).gameObject.SetActive(false);root.SetActive(false);var before=Shot(c,from,at,ev+"/old-before.png");old.SetActive(false);root.SetActive(true);Check(before.SequenceEqual(Shot(c,from,at,ev+"/old-after.png")),"Existing pixels changed");UnityEngine.Object.DestroyImmediate(old);
 foreach(Transform t in root.transform)t.gameObject.SetActive(new[]{"ruins_47","ruins_48"}.Contains(t.name));c.orthographic=true;var centre=new Vector3(-7,4.4f,-8.5f);
 foreach(string view in new[]{"normal","close","opposite","rear"}){sun.transform.rotation=view=="opposite"?Quaternion.Euler(27,130,0):Quaternion.Euler(38,-28,0);c.orthographicSize=view=="normal"?5f:3.4f;Shot(c,centre+new Vector3(view=="rear"?-5:5,4,view=="rear"?-7:7),centre,ev+"/portals-"+view+".png");}
 // Isolated geometry-identical no-ornament reference, same lighting and camera.
 sun.transform.rotation=Quaternion.Euler(38,-28,0);var carved=root.transform.Find("ruins_47").GetComponent<MeshRenderer>().sharedMaterial;var plain=root.transform.Find("ruins_7").GetComponent<MeshRenderer>().sharedMaterial;Check(!plain.IsKeywordEnabled("_RUINS_ORNAMENT"),"Plain comparison material");
 root.transform.Find("ruins_48").gameObject.SetActive(false);var portal=root.transform.Find("ruins_47").GetComponent<MeshRenderer>();c.orthographicSize=2.7f;centre=new Vector3(-7,4.5f,-7);Shot(c,centre+new Vector3(4,3,7),centre,ev+"/opening-carved.png");var mf=portal.GetComponent<MeshFilter>();var sourceMesh=mf.sharedMesh;var plainMesh=UnityEngine.Object.Instantiate(sourceMesh);var probe=JsonUtility.FromJson<UvProbe>(File.ReadAllText("Assets/Editor/opening-plain-probes.json"));Check(probe.uv.Length==plainMesh.vertexCount*2,"Plain UV count");plainMesh.uv=Enumerable.Range(0,plainMesh.vertexCount).Select(i=>new Vector2(probe.uv[i*2],probe.uv[i*2+1])).ToArray();mf.sharedMesh=plainMesh;portal.sharedMaterial=plain;Shot(c,centre+new Vector3(4,3,7),centre,ev+"/opening-plain.png");portal.sharedMaterial=carved;mf.sharedMesh=sourceMesh;UnityEngine.Object.DestroyImmediate(plainMesh);
 foreach(Transform t in root.transform)t.gameObject.SetActive(true);Physics.SyncTransforms();int rays=0;foreach(int id in new[]{47,48}){var col=root.transform.Find("ruins_"+id).GetComponent<MeshCollider>();float z=id==47?-7:-10;Check(col.sharedMesh==col.GetComponent<MeshFilter>().sharedMesh,"Collider identity");foreach(float x in new[]{-8.5f,-5.5f}){Check(col.Raycast(new Ray(new Vector3(x,3.8f,z+1),Vector3.back),out var hit,2),"Jamb collision");rays++;}Check(!col.Raycast(new Ray(new Vector3(-7,3.8f,z+1),Vector3.back),out var none,2),"Opening blocked");
 var walker=new GameObject("PortalWalker");var cc=walker.AddComponent<CharacterController>();cc.height=1.6f;cc.center=new Vector3(0,.8f,0);cc.radius=.25f;cc.skinWidth=.015f;cc.stepOffset=.25f;walker.transform.position=new Vector3(-7,3.03f,z+1);Physics.SyncTransforms();for(int k=0;k<40;k++)cc.Move(new Vector3(0,-.025f,-.05f));Check(walker.transform.position.z<z-.9f&&Math.Abs(walker.transform.position.y-3)<.1f,"Portal walk "+id);UnityEngine.Object.DestroyImmediate(walker);
 foreach(int count in new[]{9,225}){var clones=Enumerable.Range(0,count).Select(k=>{var o=UnityEngine.Object.Instantiate(col.gameObject);o.transform.position=new Vector3(100+k*5,0,100);return o;}).ToArray();Check(clones.Select(o=>o.GetComponent<MeshFilter>().sharedMesh).Distinct().Count()==1&&clones.Select(o=>o.GetComponent<MeshRenderer>().sharedMaterial).Distinct().Count()==1,"Shared references");foreach(var o in clones)UnityEngine.Object.DestroyImmediate(o);}}
 Check(!ShaderUtil.ShaderHasError(carved.shader),"Shader error");File.WriteAllText(ev+"/result.json","{\"pass\":true,\"oldMeshes\":46,\"prefabScenePixelDelta\":0,\"otherPartsPixelDelta\":0,\"capsulePassages\":2,\"jambRays\":"+rays+",\"shared9And225Offscreen\":true,\"GPUmeasured\":false}");EditorApplication.Exit(0);
 }catch(Exception e){File.WriteAllText(ev+"/failure.txt",e.ToString());Debug.LogException(e);EditorApplication.Exit(1);}}
}
